<?php if ($homeCards): ?><section class="destination-section"><div class="container section"><div class="section-head"><div><span class="eyebrow"><?= e($destinationConfig['eyebrow']) ?></span><h2><?= e($destinationConfig['title']) ?></h2><p><?= e($destinationConfig['description']) ?></p></div><span class="decor-star" aria-hidden="true"><i class="material-icons" aria-hidden="true">auto_awesome</i></span></div><div class="destination-grid"><?php foreach ($homeCards as $d): ?><a href="<?= e(destination_url($d)) ?>" class="destination-card"><img src="<?= e(tour_image($d['cover'])) ?>" alt="<?= e($d['name']) ?>" loading="lazy" width="500" height="600"><div><h3><?= e($d['name']) ?></h3><span><?= (int)$d['total'] ?> โปรแกรม</span></div><b><i class="material-icons" aria-hidden="true">north_east</i></b></a><?php endforeach ?></div></div></section><?php endif ?>
